def forward(groups):
    value, unit = groups
    unit_multipliers = {'B': 1, 'KB': 1024, 'MB': 1024**2}
    bytes_value = float(value) * unit_multipliers[unit]
    return {'stored': [int(round(bytes_value))], 'layout': [unit]}

def inverse(record):
    bytes_value = record['stored'][0]
    unit = record['layout'][0]
    unit_multipliers = {'B': 1, 'KB': 1024, 'MB': 1024**2}
    for u, m in unit_multipliers.items():
        if m == unit_multipliers[unit]:
            return f'(estimated size {bytes_value / m:.1f} {u})'
